## 3. Pure Math Module

New file: `packages/web/src/grid/interaction/math/all-day.create.ts`

```typescript
export interface NormalizedDayRange {
  startDay: string; // "YYYY-MM-DD"
  endDay: string;   // "YYYY-MM-DD" (inclusive)
}

export interface ClampedAllDayCreateRangeInput {
  anchorDate: string;
  currentDate: string;
  minDate: string;
  maxDate: string;
}

export interface AllDayScheduleDates {
  startDate: string; // "YYYY-MM-DD"
  endDate: string;   // "YYYY-MM-DD" (exclusive, i.e. endDay + 1 day)
}

/**
 * Normalizes two YYYY-MM-DD date strings so startDay <= endDay lexicographically/chronologically.
 */
export function normalizeDayRange(dateA: string, dateB: string): NormalizedDayRange;

/**
 * Clamps a YYYY-MM-DD date string within [minDate, maxDate].
 */
export function clampDayToVisibleBounds(
  date: string,
  minDate: string,
  maxDate: string,
): string;

/**
 * Converts the last inclusive date string of a multi-day span into an exclusive endDate (+1 day).
 */
export function toExclusiveAllDayEndDate(lastInclusiveDate: string): string;

/**
 * Pure calculation resolving normalized, clamped inclusive span and exclusive schedule dates.
 */
export function calculateAllDayCreateSchedule({
  anchorDate,
  currentDate,
  minDate,
  maxDate,
}: ClampedAllDayCreateRangeInput): AllDayScheduleDates;
```

